  const [posts, setPosts] = useState([
    { id: 1, title: 'Javascript', body: 'Description' },
    { id: 2, title: 'Javascript', body: 'Description' },
    { id: 3, title: 'Javascript', body: 'Description' },
  ]);

  return (
    <div className='App'>
      <PostList post={posts} />
    </div>
  );
}

export default App;
